import torch


def run(inp, dims):
    return torch.flip(inp, dims)


def gen_inputs(ctx, device):
    # Reproduces test_flip_with_non_dense_input: build a dilated tensor and
    # slice [::2, ::2] to obtain a non-contiguous (strided) input.
    shape = ctx["inp__shape"]
    dtype = getattr(torch, ctx["inp__dtype"])
    dilated = list(shape)
    dilated[0] = dilated[0] * 2
    dilated[1] = dilated[1] * 2
    if dtype.is_floating_point:
        base = torch.randn(dilated, dtype=dtype, device=device)
    else:
        base = torch.randint(-1000, 1000, dilated, device=device).to(dtype)
    return {"inp": base[::2, ::2]}
